export const CustomerCheckoutPreviewSource = "query CustomerCheckoutPreview($input: CheckoutInput!) {\n  checkoutPreview(input: $input) {\n    ...CheckoutPreviewFields\n  }\n}\n\nfragment CheckoutPreviewFields on CheckoutPreview {\n  quoteVersion\n  placeable\n  lines {\n    productVariantId\n    productName\n    sku\n    attributes\n    quantity\n    unitPrice\n    subtotal\n  }\n  totals {\n    merchandiseSubtotal\n    shippingCharge\n    total\n    currency\n  }\n  details {\n    ...CheckoutDetailsFields\n  }\n  issues {\n    code\n    productVariantId\n    message\n  }\n  availableShippingOptions {\n    method\n    charge\n    currency\n    estimate\n    supportedCountries\n  }\n}\n\nfragment CheckoutDetailsFields on CheckoutDetails {\n  contactEmail\n  contactPhone\n  paymentSelection\n  shippingAddress {\n    firstName\n    lastName\n    city\n    countryCode\n    postalCode\n    addressLine1\n    addressLine2\n    phone\n  }\n  billingAddress {\n    firstName\n    lastName\n    city\n    countryCode\n    postalCode\n    addressLine1\n    addressLine2\n    phone\n  }\n  shipping {\n    method\n    charge\n    currency\n    estimate\n    supportedCountries\n    pickupLocation {\n      name\n      address {\n        firstName\n        lastName\n        city\n        countryCode\n        postalCode\n        addressLine1\n        addressLine2\n        phone\n      }\n    }\n  }\n}";
